import json,gzip,base64,bisect,sys,html
from pathlib import Path
p=Path(sys.argv[1]);rec=json.load(open(p/'slp_01.json'));a=json.load(gzip.open(p/'slp_01_log.json.gz','rt'));rr=[dict(zip(a['keys'],r))for r in a['log']];tt=[r['t']for r in rr];poll=[json.loads(l)for l in open(p/'game_01_food_live.jsonl')];poll=[r for r in poll if r.get('trace_t') is not None];frames=[]
for i,l in enumerate(open(p/'game_01_camera.jsonl')):
 c=json.loads(l);q=min(poll,key=lambda q:abs(q['elapsed']-c['t']));t=q['trace_t'];r=rr[min(len(rr)-1,bisect.bisect_left(tt,t))];frames.append({'n':i+1,'capture':c['t'],'trace':t,'delta':abs(q['elapsed']-c['t']),'image':'data:image/jpeg;base64,'+base64.b64encode((p/c['file']).read_bytes()).decode(),'data':{k:r.get(k) for k in ['L','mode','cmd','boost','v10_routes','v10_route_id','v10_selection_reason','v10_closure_risk','v10_clear','v10_pellet_value','cause','v10_reject']}})
template='''<!doctype html><html lang="ko"><meta charset="utf-8"><title>V10 전체 타임라인</title><style>body{background:#0e1520;color:#e8edf5;font:14px system-ui;margin:16px}header{position:sticky;top:0;background:#0e1520;padding:8px;z-index:2}h1{font-size:20px}button,input{padding:6px}input[type=range]{width:55%}.grid{display:grid;grid-template-columns:1fr 270px;gap:12px}img{width:100%}pre{white-space:pre-wrap}canvas{width:100%;height:100px}small{color:#acbbcf}@media(max-width:800px){.grid{display:block}}</style><header><h1>TITLE</h1><small>모든 촬영 프레임. 촬영 시간과 판단 시간은 별도이며 가장 가까운 수집 시점으로 연결했습니다. RISK는 확률이 아닌 위험지수입니다.</small><p><button id="prev">◀</button><input id="pos" type="range" min="0"><button id="next">▶</button><button id="play">재생</button> <input id="num" type="number" min="1" style="width:70px"><span id="stamp"></span></p><canvas id="chart" width="1200" height="100"></canvas></header><div class="grid"><img id="shot"><div id="info"></div></div><script>const f=DATA,p=document.getElementById('pos'),n=document.getElementById('num');p.max=f.length-1;p.value=0;n.max=f.length;let timer;function draw(){const i=+p.value,x=f[i];n.value=i+1;document.getElementById('shot').src=x.image;document.getElementById('stamp').textContent=` ${x.n}/${f.length}F · 촬영 ${x.capture.toFixed(2)}초 · 판단 ${x.trace.toFixed(2)}초`;document.getElementById('info').textContent='';const pre=document.createElement('pre');pre.textContent=JSON.stringify(x.data,null,2);document.getElementById('info').append(pre);const c=document.getElementById('chart'),g=c.getContext('2d'),mx=Math.max(...f.map(z=>z.data.L));g.clearRect(0,0,c.width,c.height);g.strokeStyle='#67df9c';g.beginPath();f.forEach((z,k)=>{const xx=k/(f.length-1)*c.width,yy=95-z.data.L/mx*90;k?g.lineTo(xx,yy):g.moveTo(xx,yy)});g.stroke();g.strokeStyle='#ffcc66';g.beginPath();g.moveTo(i/(f.length-1)*c.width,0);g.lineTo(i/(f.length-1)*c.width,100);g.stroke();}p.oninput=draw;n.onchange=()=>{p.value=Math.max(0,Math.min(f.length-1,+n.value-1));draw()};document.getElementById('prev').onclick=()=>{p.value=Math.max(0,+p.value-1);draw()};document.getElementById('next').onclick=()=>{p.value=Math.min(f.length-1,+p.value+1);draw()};document.getElementById('play').onclick=()=>{if(timer){clearInterval(timer);timer=null}else timer=setInterval(()=>{p.value=(+p.value+1)%f.length;draw()},500)};document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')document.getElementById('next').click();if(e.key==='ArrowLeft')document.getElementById('prev').click()});draw();</script></html>'''
title=f"{rec['ext']} · 전체 {len(frames)}F · 기록 {rec['seconds']}초 · 최대 길이 {rec['L_max']}"
(p/'full_timeline.html').write_text(template.replace('TITLE',html.escape(title)).replace('DATA',json.dumps(frames,ensure_ascii=False)));print(p/'full_timeline.html')
